// Deliberately self-contained: the Worker serves this function as a browser script.
export default function boot(portfolioTools){
 'use strict';
 const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal');
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const date=s=>{const d=new Date(String(s).slice(0,10)+'T12:00:00Z');return Number.isNaN(d.getTime())?String(s||'Date unavailable'):d.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'})};
 const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:'#'}catch{return '#'}};
 const sourceURL=e=>e.document?.url?safeURL(e.document.url)+'#page='+Number(e.page):'#';
 const sourceLink=(doc,label='Original source ↗',page)=>doc?.url?`<a class="source-link" href="${escape(safeURL(doc.url)+(page?'#page='+Number(page):''))}" target="_blank" rel="noopener noreferrer">${escape(label)}</a>`:`<span class="source-type">Uploaded on this device</span>`;
 function loadLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
 const state={view:'briefing',library:null,briefs:[],caseStudy:null,ticker:'INFY',query:'',result:null,filter:'all',window:'apr26',saved:loadLocal('finn-saved',[]),prefs:loadLocal('finn-prefs',{priceThreshold:4,volumeThreshold:2,results:true,management:true}),uploads:[],search:'',busy:false,request:null,diligence:null,theses:loadLocal('finn-theses',[]),activeThesis:null,thesisDraft:null,thesisBusy:false,imported:loadLocal('finn-holdings',null),accountFilter:'all',quoteMap:{},pricesLoading:false,priceLastAt:null,priceError:'',priceAuto:true,commandBusy:false,commandHistory:loadLocal('finn-commands',[]),plan:null,workspaceTickers:[],stage:'',resultTab:'answer'};
 let toastTimer,dbPromise,priceTimer;
 const toast=text=>{$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400)};
 function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Device storage is full. This change could not be saved.');return false}}
 async function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('finn-documents',1);req.onupgradeneeded=()=>req.result.createObjectStore('documents',{keyPath:'document.id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise}
 async function localDocs(action,value){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('documents',action==='getAll'?'readonly':'readwrite');const store=tx.objectStore('documents');let req=action==='getAll'?store.getAll():action==='put'?store.put(value):store.delete(value);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
 const extraCorpus=()=>({documents:state.uploads.filter(u=>u.document.ticker===state.ticker).map(u=>u.document),chunks:state.uploads.filter(u=>u.document.ticker===state.ticker).flatMap(u=>u.chunks)});
 const docs=()=>[...(state.library?.documents||[]),...state.uploads.map(u=>u.document)];
 const covered=ticker=>docs().some(d=>d.ticker===ticker);
 const coveredCount=()=>watchlist().filter(c=>covered(c.ticker)).length;
 const watchlist=()=>state.imported?portfolioTools.consolidate(state.imported.rows).holdings:state.library?.portfolio||[];
 const company=ticker=>watchlist().find(c=>c.ticker===ticker)?.name||state.library?.portfolio.find(c=>c.ticker===ticker)?.name||ticker;
 const activeThesis=()=>state.theses.find(t=>t.id===state.activeThesis);
 const currentResult=()=>state.view==='thesis'?activeThesis()?.reviews?.at(-1)?.result:state.result;
 const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata'}).format(new Date());
 const nextMonth=()=>{const d=new Date(today()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+30);return d.toISOString().slice(0,10)};
 const money=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});
 async function api(path,options={}){const response=await fetch(path,options);const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data}
 const post=(path,body,signal)=>api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal});
 function heading(title,subtitle,button=''){return `<div class="page-heading"><div><h1>${title.replace(/<br\s*\/?>/g,' ')}</h1><p>${subtitle}</p></div>${button}</div>`}
 function empty(title,message,action=''){return `<div class="empty-state"><span class="empty-symbol">↗</span><h3>${escape(title)}</h3><p>${escape(message)}</p>${action}</div>`}
 function renderCoverageGap(r){const missing=r.coverage?.tickers||[state.ticker];return `<div class="notebook-top"><span>SOURCE COVERAGE / ACTION REQUIRED</span><span class="result-status evidence">NO MODEL GUESS</span></div><div class="coverage-gap"><div class="gap-icon">▤<span>＋</span></div><span class="eyebrow">${escape(missing.join(' / '))} · SOURCES NEEDED</span><h2>The next step is<br>the original document.</h2><p>${escape(r.summary)}</p><div class="gap-question"><small>YOUR INVESTIGATION IS READY</small><strong>${escape(r.query)}</strong></div>${missing.map(t=>`<div class="gap-actions"><button class="solid-button" data-action="discover" data-ticker="${escape(t)}">Find ${escape(t)} disclosures ↗</button><button class="outline-button" data-action="import" data-ticker="${escape(t)}">＋ Import PDF</button></div>`).join('')}<p class="micro-note">No indexed sources means we cannot answer yet. It does not mean management provided no guidance. Import a relevant PDF, then run your question again.</p><div class="gap-alternative"><span>Explore an indexed company</span>${[...new Set(docs().map(d=>d.ticker))].map(t=>`<button data-action="research-company" data-ticker="${escape(t)}">${escape(t)} ↗</button>`).join('')}</div></div>`}
 function paintCommandHistory(){const target=$('#recent-commands');if(!target)return;target.innerHTML=state.commandHistory.slice(0,5).map(h=>`<button data-command="${escape(h.prompt)}" title="Rerun: ${escape(h.prompt)}"><span>↗</span><div>${escape(h.prompt)}<small>${escape(h.action||'investigation')} · ${escape(new Date(h.at).toLocaleDateString('en-IN',{day:'numeric',month:'short'}))}</small></div></button>`).join('')||'<p class="sidebar-empty">Your investigations build a trail here.</p>'}
 function commandStatus(text,steps=[],status='running'){const el=$('#command-status');el.className='command-status visible '+status;el.innerHTML=`<span class="${status==='running'?'loader':'status-check'}">${status==='running'?'':status==='done'?'✓':'!'}</span><span>${escape(text)}</span><div>${steps.map(s=>`<span>${escape(s)}</span>`).join('<i>→</i>')}</div>`}
 async function fetchWorkspaceQuotes(tickers){if(!tickers.length)return;try{const r=await api('/api/quotes?tickers='+encodeURIComponent(tickers.join(',')));r.quotes.forEach(q=>state.quoteMap[q.ticker]=q);if(state.view==='briefing'){const tape=$('#overview-tape');if(tape)tape.innerHTML=watchlist().slice(0,5).map(c=>tapeRow(c.ticker)).join('');const foot=$('.market-foot');if(foot)foot.innerHTML='<span class="live-dot"></span>Provider timestamps in quote details <button class="text-button" data-action="refresh-overview" aria-label="Refresh overview prices">↻</button>'}if(state.view==='research'){const target=$('.workspace-quotes');if(target)target.innerHTML=state.workspaceTickers.map(tapeRow).join('')+'<p>Provider quotes may be delayed · open a quote for its timestamp.</p>'}}catch{if(state.view==='briefing'){const foot=$('.market-foot');if(foot)foot.innerHTML='Quote provider unavailable. <button class="text-button" data-action="refresh-overview">Retry ↻</button>'}toast('Market data could not refresh. Research sources remain available.')}}
 function showCommandHelp(){openModal('One request. A working desk.',`<p class="notebook-subtitle">Name a company and what you want to investigate. FINN selects the scope, retrieves its disclosures and opens the result. Follow-up questions use the current company.</p><div class="command-examples">${['Compare Infosys and TCS on FY27 growth guidance and show their prices','What did HDFC Bank management say about loan growth in FY26?','Show prices for Reliance and HDFC Bank','Find disclosures for ICICI Bank','Open my portfolio','Create a thesis for Infosys','Import a company PDF','Save this research note','Export this research note','Pause price auto refresh'].map(p=>`<button data-command="${escape(p)}">${escape(p)}<span>↗</span></button>`).join('')}</div><p class="micro-note">Research uses indexed primary documents. Quotes are requested separately. Commands can open the PDF or CSV import flow; you choose the local file. Ctrl / ⌘ K focuses the command bar.</p>`)}
 async function runCommand(prompt){
  if(!state.library){toast('The workspace is still opening.');return}if(state.commandBusy||state.busy||state.thesisBusy){toast('An investigation is running. Finish or cancel it first.');return}
  prompt=String(prompt).trim();if(prompt.length<3)return;modal.close();$('#workspace-command').value=prompt;state.commandBusy=true;$('#command-submit').disabled=true;commandStatus('Understanding your request…');
  let plan;
  try{
   plan=await post('/api/command',{prompt,context:{ticker:state.ticker}});state.plan=plan;
   if(plan.action==='clarify'){commandStatus(plan.message,[],'attention');return}
   if(plan.tickers[0])state.ticker=plan.tickers[0];
   const names={research:'Research',compare:'Compare companies',prices:'Market prices',navigate:'Open workspace',discover:'Find source documents',import:'Import a source',thesis:'Open thesis file',save:'Save note',export:'Export note',pause:'Pause prices',resume:'Resume prices'};
   commandStatus(names[plan.action]+' · '+(plan.tickers.join(' × ')||plan.view||'workspace'),['Scope resolved',plan.includePrices?'Market data + documents':'Workspace action']);
   if(plan.action==='research'){
    const pending=investigate(plan.query,plan.tickers[0]||state.ticker);if(plan.includePrices){state.workspaceTickers=plan.tickers.length?plan.tickers:[state.ticker];render();fetchWorkspaceQuotes(state.workspaceTickers)}await pending;if(!state.result){commandStatus('Investigation cancelled.',[],'attention');return}
   }else if(plan.action==='compare'){
    state.query=plan.query;state.result=null;state.busy=true;state.stage='Comparing disclosures across '+plan.tickers.join(' and ')+'.';state.request=new AbortController();state.workspaceTickers=plan.includePrices?plan.tickers:[];setView('research');if(plan.includePrices)fetchWorkspaceQuotes(plan.tickers);
    try{const extra={documents:state.uploads.filter(u=>plan.tickers.includes(u.document.ticker)).map(u=>u.document),chunks:state.uploads.filter(u=>plan.tickers.includes(u.document.ticker)).flatMap(u=>u.chunks)};state.result=await post('/api/compare',{tickers:plan.tickers,query:plan.query,extraCorpus:extra},state.request.signal)}finally{state.busy=false;state.request=null;render()}
   }else if(plan.action==='prices'){
    if(plan.tickers.length){state.result=null;state.query='';state.workspaceTickers=plan.tickers;setView('research');await fetchWorkspaceQuotes(plan.tickers)}else setView('portfolio');
   }else if(plan.action==='navigate')setView(plan.view);
   else if(plan.action==='discover'){setView('research');state.result=null;render();await discover(state.ticker)}
   else if(plan.action==='import'){if(/csv|holdings|portfolio/i.test(prompt))showHoldingsImport();else showImport(state.ticker)}
   else if(plan.action==='thesis'){state.activeThesis=state.theses.find(t=>t.ticker===state.ticker)?.id||null;state.thesisDraft=null;setView('thesis')}
   else if(plan.action==='save'||plan.action==='export'){if(!currentResult()){commandStatus('Run a research question before saving or exporting.',[],'attention');return}plan.action==='save'?saveResearch():exportResearch()}
   else if(plan.action==='pause'||plan.action==='resume'){state.priceAuto=plan.action==='resume';setView('portfolio');if(!state.priceAuto)pausePrices();paintQuotes()}
   const gap=['research','compare'].includes(plan.action)&&state.result?.mode==='coverage';
   commandStatus(gap?'Sources needed · your question is ready':(state.result?.mode==='evidence'&&['research','compare'].includes(plan.action)?'Original evidence retrieved · synthesis unavailable':names[plan.action]+' · ready'),[plan.planner||'Scope resolved',...(plan.tickers.length?[plan.tickers.join(' × ')]:[]),gap?'Add company disclosures':['research','compare'].includes(plan.action)?'Evidence attached':'Completed'],gap?'attention':'done');
   state.commandHistory=[{prompt,action:plan.action,at:new Date().toISOString()},...state.commandHistory.filter(h=>h.prompt!==prompt)].slice(0,12);persist('finn-commands',state.commandHistory);paintCommandHistory();
  }catch(error){commandStatus(error.name==='AbortError'?'Investigation cancelled.':error.message,[],'attention')}
  finally{state.commandBusy=false;$('#command-submit').disabled=false}
 }
 document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#workspace-command').focus();$('#workspace-command').select()}});
 function setView(view,updateHash=true){if(!['briefing','research','thesis','portfolio','library','saved'].includes(view))view='briefing';state.view=view;state.search='';if(updateHash&&location.hash!=='#'+view)history.replaceState(null,'','#'+view);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const labels={briefing:'Overview',research:'Research desk',thesis:'Thesis file',portfolio:'My portfolio',library:'Source library',saved:'Saved notes'};$('#breadcrumb').textContent=labels[view];render();if(view==='portfolio')refreshPrices();else pausePrices();window.scrollTo({top:0,behavior:'instant'})}
 function render(){if(!state.library)return;const count=$('.nav-item[data-view="portfolio"] .nav-count');if(count)count.textContent=watchlist().length;main.innerHTML=state.view==='briefing'?renderBriefing():state.view==='research'?renderResearch():state.view==='thesis'?renderThesis():state.view==='portfolio'?renderPortfolio():state.view==='library'?renderLibrary():renderSaved();if(state.view==='portfolio')paintQuotes();paintCommandHistory()}
 function miniChart(q){const values=q?.intraday?.map(p=>p.price).filter(Number.isFinite)||[];if(values.length<2)return '<span class="spark-empty">Awaiting quote</span>';const lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1;return `<svg viewBox="0 0 100 30" aria-hidden="true"><polyline points="${values.map((v,i)=>`${i/(values.length-1)*100},${27-(v-lo)/span*24}`).join(' ')}" fill="none" stroke="currentColor" stroke-width="1.6" vector-effect="non-scaling-stroke"/></svg>`}
 function tapeRow(ticker){const q=state.quoteMap[ticker],valid=Number.isFinite(q?.price);return `<button class="tape-row" data-action="${valid?'quote-details':'research-company'}" data-ticker="${escape(ticker)}"><span class="ticker-monogram">${escape(ticker.slice(0,2))}</span><span class="tape-name"><b>${escape(ticker)}</b><small>${escape(company(ticker))}</small></span><span class="tape-spark ${q?.changePercent<0?'down':'up'}">${miniChart(q)}</span><span class="tape-price"><b>${valid?money(q.price):'—'}</b><small class="${q?.changePercent<0?'down':'up'}">${valid?(q.changePercent===null?'Change unavailable':(q.changePercent>=0?'+':'')+q.changePercent.toFixed(2)+'%'):'No provider quote'}</small></span></button>`}
 function guidanceVisual(){const c=state.caseStudy;if(!c)return '';const xs=[65,210,355,500],y=v=>218-v*43;const upper=c.revisions.map((r,i)=>`${xs[i]},${y(r.high)}`).join(' '),lower=c.revisions.map((r,i)=>`${xs[i]},${y(r.low)}`).reverse().join(' ');return `<div class="trajectory-chart"><svg viewBox="0 0 570 265" role="img" aria-label="Infosys FY26 constant-currency growth guidance raised from 0–3 percent to 3–3.5 percent. Actual growth was 3.1 percent."><defs><linearGradient id="guidance-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c0dc84" stop-opacity=".4"/><stop offset="1" stop-color="#c0dc84" stop-opacity=".03"/></linearGradient></defs>${[0,1,2,3,4].map(v=>`<line x1="38" y1="${y(v)}" x2="535" y2="${y(v)}" stroke="#303943" stroke-dasharray="3 5"/><text x="12" y="${y(v)+4}" fill="#8995a2" font-size="10">${v}%</text>`).join('')}<polygon points="${upper} ${lower}" fill="url(#guidance-fill)"/><polyline points="${upper}" fill="none" stroke="#c6e68f" stroke-width="2"/><polyline points="${c.revisions.map((r,i)=>`${xs[i]},${y(r.low)}`).join(' ')}" fill="none" stroke="#c6e68f" stroke-width="2"/>${c.revisions.map((r,i)=>`<circle cx="${xs[i]}" cy="${y(r.high)}" r="4" fill="#c6e68f"/><text x="${xs[i]}" y="${y(r.high)-16}" text-anchor="middle" fill="#eef6e5" font-size="12">${r.low}–${r.high}%</text><text x="${xs[i]}" y="245" text-anchor="middle" fill="#8995a2" font-size="10">${['APR 25','JUL 25','OCT 25','JAN 26'][i]}</text>`).join('')}<circle cx="500" cy="${y(c.actual.value)}" r="6" fill="#1c252d" stroke="#f5f7f1" stroke-width="2"/></svg></div>`}
 function renderBriefing(){
  const latest=docs().map(d=>d.date).sort().at(-1),marketTickers=watchlist().slice(0,5).map(c=>c.ticker),quoted=marketTickers.map(t=>state.quoteMap[t]).filter(q=>Number.isFinite(q?.price));
  return `<div class="desk-heading"><div><span class="eyebrow">THE BIG PICTURE</span><h1>Your research, in motion<span>.</span></h1><p>Follow the numbers. Challenge the narrative. Keep the source close.</p></div><button class="outline-button" data-action="import">＋ Add a source</button></div>
  <div class="desk-metrics"><div><span>COMPANIES ON RADAR</span><b>${watchlist().length}<small>Illustrative watchlist${state.imported?' · imported':''}</small></b></div><div><span>RESEARCH COVERAGE</span><b>${coveredCount()}<em>/ ${watchlist().length}</em><small>Companies with indexed sources</small></b></div><div><span>PRIMARY DOCUMENTS</span><b>${docs().length}<small>Latest indexed · ${escape(date(latest))}</small></b></div><div><span>RESEARCH ENGINE</span><b class="engine-metric"><i></i>${state.library.providerConfigured?'Gemini':'Retrieval'}<small>${state.library.providerConfigured?'Connected · citations required':'Original passages available'}</small></b></div></div>
  <div class="overview-grid"><section class="trajectory-panel"><div class="panel-top"><span class="eyebrow"><i class="live-dot"></i> THE GUIDANCE TRAIL</span><button data-action="open-case" class="panel-link">Investigate ↗</button></div><div class="trajectory-heading"><div><span>INFOSYS / FY26 / HISTORICAL CASE</span><h2>The outlook kept moving.<br>The evidence stayed.</h2></div><div class="trajectory-actual"><b>3.1<span>%</span></b><small>FULL-YEAR ACTUAL</small></div></div>${guidanceVisual()}<div class="trajectory-foot"><span><i></i> Constant-currency revenue growth guidance</span><button data-action="case-evidence">5 source passages ↗</button></div><div class="timeline-controls">${(state.caseStudy?.revisions||[]).map((r,i)=>`<button data-action="case-passage" data-index="${i}"><small>${['INITIAL','REVISION 01','REVISION 02','FINAL'][i]}</small><b>${r.low}–${r.high}%</b><span>${escape(date(r.date))} ↗</span></button>`).join('')}</div></section>
  <section class="market-panel"><div class="panel-top"><h2 class="section-title">THE MARKET TAPE</h2><button class="text-button" data-view="portfolio">All ${watchlist().length} ↗</button></div><p class="panel-description">Latest provider quotes · NSE</p><div id="overview-tape">${marketTickers.map(tapeRow).join('')}</div><div class="market-foot"><span class="live-dot"></span>${quoted.length?'Provider timestamps in quote details':'Fetching market data…'}<button class="text-button" data-action="refresh-overview" aria-label="Refresh overview prices">↻</button></div><p class="micro-note">Quotes may be delayed. Open the portfolio for 60-second updates.</p></section>
  <section class="signals-panel"><div class="panel-top"><h2 class="section-title">QUESTIONS WORTH FOLLOWING</h2><span class="panel-caption">SOURCE ARCHIVE / HISTORICAL</span></div><div class="signal-grid">${state.briefs.filter(b=>!state.imported||watchlist().some(c=>c.ticker===b.ticker)).map((b,i)=>`<button class="signal-card" data-action="research-brief" data-id="${b.id}"><div><span class="signal-number">0${i+1}</span><span class="company-chip">${escape(b.ticker)}</span><span class="signal-arrow">↗</span></div><h3>${escape(b.headline)}</h3><p>${escape(b.deck)}</p><small>${escape(b.document.period)} · ${escape(date(b.date))}</small></button>`).join('')||'<p class="micro-note">No archived signals match your imported companies. Ask a research question above.</p>'}</div></section>
  <section class="coverage-panel"><div class="panel-top"><h2 class="section-title">THE EVIDENCE MAP</h2><button class="text-button" data-view="library">Library ↗</button></div><div class="coverage-large"><b>${state.library.chunkCount.toLocaleString('en-IN')}</b><span>page-linked passages</span></div><div class="coverage-company-grid">${watchlist().map(c=>`<button data-action="research-company" data-ticker="${escape(c.ticker)}" class="${covered(c.ticker)?'indexed':'not-indexed'}" title="${escape(c.name)} · ${covered(c.ticker)?'Documents indexed':'Sources needed'}"><i></i>${escape(c.ticker)}</button>`).join('')}</div><div class="coverage-legend"><span><i></i> Indexed</span><span><i></i> Needs sources</span></div><p class="micro-note">Coverage is a starting point, not a guarantee that a question is answered.</p></section></div>
  <section class="start-command"><div class="start-command-icon">↗</div><div><span class="eyebrow">LET THE DESK DO THE WORK</span><h2>A question can open an entire investigation.</h2></div><button class="outline-button" data-command="Compare Infosys and TCS on FY27 growth guidance and show their prices">Try a comparison ↗</button></section>`;
 }
 function article(b,i){const saved=state.saved.some(s=>s.id===b.id);const meta=`<div class="article-meta"><span class="company-chip">${escape(b.ticker)}</span><span class="sep">/</span><span>${escape(b.document.period)}</span><span class="sep">/</span><time>${escape(date(b.date))}</time></div>`;const bookmark=`<button class="bookmark ${saved?'saved':''}" data-action="bookmark" data-id="${b.id}" aria-label="${saved?'Remove bookmark':'Bookmark '+escape(b.company)}" aria-pressed="${saved}">${saved?'✓':'⌑'}</button>`;
  if(!i)return `<article class="lead-article">${meta}<div class="article-kicker">${escape(b.label)} · EDITOR’S PICK</div><h2>${escape(b.headline)}</h2><p class="deck">${escape(b.deck)}</p><span class="lead-watermark" aria-hidden="true">f.</span><div class="lead-actions"><button class="solid-button" data-action="research-brief" data-id="${b.id}">Follow the evidence <span>↗</span></button>${bookmark}</div></article>`;
  return `<article class="article-row"><span class="article-number">0${i+1}</span><div>${meta}<h3>${escape(b.headline)}</h3><p>${escape(b.deck)}</p><div class="article-bottom"><button class="text-button" data-action="research-brief" data-id="${b.id}">Investigate ↗</button>${sourceLink(b.document,'Read the transcript ↗')}</div></div>${bookmark}</article>`;
 }
 function researchPrompts(){return /BANK/.test(state.ticker)?['What did management say about loan and deposit growth through FY26?','How did net interest margins and funding costs change?','What asset-quality risks does management identify?']:['How did revenue growth guidance change through FY26?','Do accounting profits turn into operating cash flow?','What risks and headwinds does management identify?']}
 function scopeSummary(){const tickers=state.result?.scope||state.workspaceTickers.length&&state.workspaceTickers||[state.ticker];return tickers.map(ticker=>{const source=docs().filter(d=>d.ticker===ticker).sort((a,b)=>a.date.localeCompare(b.date));return `<div class="scope-company"><span class="ticker-monogram">${escape(ticker.slice(0,2))}</span><div><b>${escape(ticker)}</b><small>${escape(company(ticker))}</small></div><span class="scope-count ${source.length?'':'missing'}">${source.length?source.length+' doc'+(source.length===1?'':'s'):'No sources'}</span></div>${source.length?`<div class="scope-dates">${escape(date(source[0].date))} → ${escape(date(source.at(-1).date))}</div>`:''}`}).join('')}
 function renderResearch(){return `<div class="desk-heading research-heading"><div><span class="eyebrow">THE RESEARCH WORKSPACE</span><h1>${state.result?.scope?.length>1?'A side-by-side view.':'Every answer has a source.'}</h1><p>Use the command bar to investigate a company, compare peers or change your view.</p></div><span class="workspace-badge">${state.busy?'<i class="live-dot"></i> READING SOURCES':state.result?.mode==='coverage'?'SOURCES NEEDED':state.result?'INVESTIGATION / COMPLETE':'READY FOR YOUR QUESTION'}</span></div>
  ${state.workspaceTickers.length?`<div class="workspace-quotes">${state.workspaceTickers.map(tapeRow).join('')}<p>Provider quotes may be delayed · open a quote for its timestamp.</p></div>`:''}
  <div class="research-layout"><section class="research-result" id="research-output" aria-live="polite" aria-busy="${state.busy}">${state.busy?`<div class="notebook-top"><span>INVESTIGATION IN PROGRESS</span><span class="loader"></span></div><div class="loading-result"><div class="reading-orbit">↗</div><h3>Following the evidence.</h3><p>${escape(state.stage||'Searching company disclosures and checking the context.')}</p><div class="run-steps"><span class="complete">01 · Scope selected</span><span class="running">02 · Retrieve & investigate</span><span>03 · Validate citations</span></div><button class="text-button" data-action="cancel-research">Cancel request</button></div>`:state.result?renderResult(state.result):state.ticker==='INFY'?renderCase():renderCompanyIntro()}</section>
  <aside class="research-control"><div class="context-header"><span class="eyebrow">INVESTIGATION SCOPE</span><span>◎</span></div>${scopeSummary()}${!covered(state.ticker)?`<div class="coverage-warning"><b>Sources needed before research</b><p>Find a company disclosure or import a PDF. Market prices are available separately.</p><button class="outline-button" data-action="discover">Find disclosures ↗</button><button class="text-button" data-action="import">＋ Import PDF</button></div>`:''}<form id="research-form"><label for="research-ticker">SWITCH COMPANY</label><div class="ticker-field"><input id="research-ticker" name="ticker" value="${escape(state.ticker)}" maxlength="24" required autocomplete="off"><button type="button" data-action="apply-ticker" aria-label="Apply company ticker">↵</button></div><details class="manual-question"><summary>Ask in this company’s file ＋</summary><label for="research-question">RESEARCH QUESTION</label><textarea id="research-question" name="query" maxlength="1200" placeholder="What changed in management’s outlook?">${escape(state.query)}</textarea><button type="submit" class="solid-button" ${state.busy?'disabled':''}>Investigate ↗</button></details></form>
  <div class="prompt-list"><div class="eyebrow">NEXT LINES OF INQUIRY</div>${researchPrompts().map((p,i)=>`<button class="prompt-button" data-prompt="${i}">${escape(p)}<span>↗</span></button>`).join('')}</div><div class="scope-files"><span class="eyebrow">IN THIS COMPANY FILE</span>${docs().filter(d=>d.ticker===state.ticker).map(d=>`<div><span>▤</span><div><b>${escape(d.period)}</b><small>${escape(date(d.date))}</small></div>${sourceLink(d,'↗')}</div>`).join('')||'<p class="micro-note">No indexed documents.</p>'}</div><div class="scope-status">${state.library.providerConfigured?'GEMINI · CITATIONS REQUIRED':'EVIDENCE MODE'}<br>Primary disclosures. Page-level references.</div></aside></div>`}
 function renderCompanyIntro(){const sources=docs().filter(d=>d.ticker===state.ticker);return `<div class="notebook-top"><span>${escape(state.ticker)} / THE SOURCE FILE</span><span>${sources.length} DOCUMENTS</span></div><h2 class="notebook-title">${escape(company(state.ticker))}</h2><p class="notebook-subtitle">${sources.length?'Ask a question to investigate these company disclosures. Every retrieved passage retains its document and page.':'This company is not indexed yet. Discover its disclosures and import a report or transcript to start researching.'}</p>${sources.map(d=>`<div class="case-source-row"><div><strong>${escape(d.title)}</strong><small>${escape(d.period)} · ${escape(date(d.date))}</small></div>${sourceLink(d,'Original ↗')}</div>`).join('')}<div class="case-actions" style="margin-top:22px"><button class="outline-button" data-action="discover">Discover disclosures ↗</button><button class="text-button" data-action="import">Import a company PDF ＋</button></div>`}
 function renderCase(){const c=state.caseStudy;if(!c)return empty('Your next question starts here.','Pick a company, ask a question, and inspect the supporting passages.');return `<div class="notebook-top"><span>THE RESEARCH NOTE / 001</span><span class="result-status">SOURCE-CHECKED EXAMPLE</span></div><h2 class="notebook-title">${escape(c.title)}</h2><p class="notebook-subtitle">Infosys started FY26 with a 0–3% growth outlook. Three revisions later, the final reported growth was 3.1%.</p><div class="case-caption">INFY · ${escape(c.targetPeriod)} · ${escape(c.metric.toUpperCase())}<br>${escape(c.basis)}</div><div class="guidance-chart" role="img" aria-label="FY26 revenue growth guidance: April 2025 0 to 3 percent, July 1 to 3, October 2 to 3, January 2026 3 to 3.5; final actual 3.1 percent.">${c.revisions.map((r,i)=>`<div class="guidance-row"><time>${escape(date(r.date).replace(/\d{4}/,'').trim())}</time><div class="range-track"><span class="range-bar ${i===3?'latest':''}" style="left:${r.low/4*100}%;width:${(r.high-r.low)/4*100}%"></span></div><strong>${r.low}–${r.high}%</strong></div>`).join('')}<div class="guidance-row"><time>FY26 actual</time><div class="range-track"><span class="actual-dot" style="left:${c.actual.value/4*100}%"></span></div><strong>${c.actual.value}%</strong></div><div class="chart-axis"><span>0%</span><span>1%</span><span>2%</span><span>3%</span><span>4%</span></div></div><div class="case-verdict"><span class="verdict-symbol">✓</span><span><strong>Within the final guidance range.</strong><br>Above the initial upper bound. The dated revisions matter.</span></div><div class="case-actions"><button class="text-button" data-action="case-evidence">Inspect the five source passages ↗</button><button class="text-button" data-action="case-research">Ask a follow-up ↗</button></div><p class="micro-note">A source-checked example of the workflow. Other questions run through the same general document search. This is a historical FY26 comparison.</p>`}
 function renderResult(r){if(r.mode==='coverage')return renderCoverageGap(r);const evidence=r.evidence||[];return `<div class="notebook-top"><span>${escape(r.scope?.join(' × ')||r.reviewContext?.ticker||state.ticker)} / RESEARCH NOTE</span><span class="result-status ${r.mode==='evidence'?'evidence':''}">${r.mode==='agent'?'AGENT RESEARCH':'RETRIEVED EVIDENCE'}</span></div><h2 class="notebook-title">${escape(r.query)}</h2><p class="notebook-subtitle">${escape(r.summary)}</p>${r.reviewContext?`<div class="review-context"><span class="eyebrow">THE THESIS UNDER REVIEW</span><p>${escape(r.reviewContext.thesis)}</p><span class="eyebrow">WHAT WOULD CHANGE MY MIND</span><p>${escape(r.reviewContext.disconfirm)}</p><div class="search-routes">${(r.evidenceGroups||[]).map(g=>`<span>${escape(g.label)} · ${g.ids.length} passages</span>`).join('')}</div></div>`:''}${r.findings.map((f,i)=>`<div class="finding"><span class="saved-label">0${i+1}</span> ${f.stance?`<span class="stance-tag ${escape(f.stance)}">${escape(f.stance)} · model interpretation</span>`:''}${escape(f.text)} ${f.evidenceIds.map(id=>`<button class="citation-button" data-evidence-id="${escape(id)}" aria-label="Read source ${evidence.findIndex(e=>e.id===id)+1}">[${evidence.findIndex(e=>e.id===id)+1}]</button>`).join('')}</div>`).join('')}
  ${r.gaps?.length?`<section class="gaps"><h3>WHAT WE KNOW / WHAT WE DON’T</h3>${r.gaps.map(g=>`<p>${escape(g)}</p>`).join('')}</section>`:''}
  <details class="trace"><summary>RESEARCH TRAIL · ${r.trace.length} recorded steps</summary><ol>${r.trace.map((t,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div><strong>${escape(t.tool.replace(/_/g,' '))}</strong>${escape(t.detail)} <span>(${(t.ms/1000).toFixed(1)}s)</span></div></li>`).join('')}</ol></details>
  <div class="section-line"><h3 class="section-title">THE SUPPORTING EVIDENCE</h3><span class="subtle">${evidence.length} passages</span></div><div class="evidence-list">${evidence.map((e,i)=>evidenceCard(e,i)).join('')||empty('No evidence found.','Add relevant company documents to expand coverage.')}</div><div class="result-actions"><button class="outline-button" data-action="save-research">Save research note ＋</button><button class="text-button" data-action="export-research">Export as Markdown ↗</button></div><p class="micro-note">Citations identify retrieved passages. They do not independently prove every model interpretation; read the original context before relying on a finding.</p>`}
 function evidenceCard(e,i){return `<article class="evidence-card" id="evidence-${i}"><div class="evidence-head"><span>[${i+1}] ${escape(e.ticker)} · ${escape(e.document?.period||'Period unspecified')}</span><span>PAGE ${Number(e.page)}</span></div><h4>${escape(e.document?.title||'Company document')}</h4><details><summary>Read the source passage</summary><blockquote>${escape(e.text)}</blockquote></details><div style="margin-top:12px">${sourceLink(e.document,'Open original · page '+e.page+' ↗',e.page)}${e.document?.provenance==='user_upload'?'<span class="external-tag"> · UPLOADED / PROVENANCE UNVERIFIED</span>':''}</div></article>`}
 function renderPortfolio(){
  const source=state.imported?portfolioTools.consolidate(state.imported.rows,state.accountFilter).holdings:watchlist(),rows=source.filter(c=>(c.name+' '+c.ticker+' '+c.sector).toLowerCase().includes(state.search.toLowerCase()));
  return `<div class="edition"><span class="eyebrow">YOUR CIRCLE OF COMPETENCE</span><span class="edition-right">${state.imported?'YOUR IMPORTED SNAPSHOT':'ILLUSTRATIVE WATCHLIST'}</span></div>${heading('Keep your companies<br><em>in view.</em>',state.imported?'Your holdings, consolidated across accounts. Source coverage remains separate from portfolio membership.':'An illustrative watchlist of 18 Indian listed companies. Import a snapshot to make it your own.',`<button class="outline-button" data-action="import-holdings">Import holdings CSV ＋</button>`)}${portfolioOverview()}${renderTracker()}<div class="toolbar"><input class="search-input" id="portfolio-search" aria-label="Filter portfolio" placeholder="Find a company or sector…" value="${escape(state.search)}"><button class="outline-button" data-action="import-holdings">${state.imported?'Replace snapshot':'Import holdings CSV'} ＋</button><button class="text-button" data-action="preferences">Signal preferences ↗</button></div><div id="quote-panel"></div><div class="portfolio-table-wrap"><table class="data-table portfolio-table"><thead><tr><th>Company</th><th class="sector-col">Sector</th><th>Latest quote</th>${state.imported?'<th>Weight</th>':''}<th class="source-col">Sources</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${escape(c.name)}</strong><small>${escape(c.ticker)} · NSE${c.accounts?' · '+c.accounts.length+' account'+(c.accounts.length===1?'':'s'):''}</small></td><td class="sector-col">${escape(c.sector)}</td><td class="quote-cell" data-quote-ticker="${escape(c.ticker)}">${quoteCell(c.ticker)}</td>${state.imported?`<td class="weight-cell">${c.weight===null?'—':c.weight.toFixed(1)+'%'}<small>${money(c.marketValue)}</small></td>`:''}<td class="source-col"><span class="pill ${covered(c.ticker)?'':'uncovered'}">${covered(c.ticker)?docs().filter(d=>d.ticker===c.ticker).length+' doc'+(docs().filter(d=>d.ticker===c.ticker).length===1?'':'s'):'Not indexed'}</span></td><td><button class="table-action" data-action="market" data-ticker="${escape(c.ticker)}">Market ↗</button> <button class="table-action" data-action="research-company" data-ticker="${escape(c.ticker)}" style="margin-left:10px">Research ↗</button><button class="table-action thesis-row-action" data-action="company-thesis" data-ticker="${escape(c.ticker)}">Thesis ↗</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('No matching companies.','Try a ticker, company name, or sector.'):''}<div class="import-callout"><div><h3>What must be true for this company?</h3><p>Keep a thesis and its disconfirming condition alongside your portfolio. Review company evidence before revising your view.</p></div><button class="outline-button" data-view="thesis">Open the thesis file ↗</button></div><p class="micro-note">The example watchlist is illustrative. Snapshot values stay on this device; market quotes are requested separately. Alerts are evaluated on request.</p>`;
 }
 function renderLibrary(){const all=docs().filter(d=>(d.title+' '+d.ticker+' '+d.period).toLowerCase().includes(state.search.toLowerCase()));return `<div class="edition"><span class="eyebrow">FOLLOW THE FOOTNOTES</span><span class="edition-right">${docs().length} PRIMARY DOCUMENTS</span></div>${heading('Start with<br><em>the original.</em>','Annual reports and management transcripts. Every passage leads back to its source.',`<button class="outline-button" data-action="import">＋ Import PDF</button>`)}<div class="toolbar"><input class="search-input" id="library-search" aria-label="Filter source library" placeholder="Search companies, periods, documents…" value="${escape(state.search)}"><button class="outline-button" data-action="import">＋ Import a company PDF</button></div><div class="library-grid">${all.map(d=>`<article class="doc-card"><span class="doc-mark">${d.type==='annual_report'?'▥':'▤'}</span><span class="source-type">${escape(d.ticker)} / ${d.type==='annual_report'?'ANNUAL REPORT':'EARNINGS TRANSCRIPT'}</span><h3>${escape(d.title)}</h3><p>${escape(d.period)} · ${Number(d.pages)} PAGES<br>${escape(date(d.date))}${d.provenance==='user_upload'?'<br>THIS DEVICE · UPLOADED / UNVERIFIED':''}</p><div class="doc-actions">${sourceLink(d,'Read original ↗')}<button data-action="research-company" data-ticker="${escape(d.ticker)}">Research ↗</button>${d.provenance==='user_upload'?`<button data-action="delete-document" data-id="${escape(d.id)}" aria-label="Delete uploaded document">×</button>`:''}</div></article>`).join('')}</div>${!all.length?empty('No documents in this selection.','Try a broader search or add a company PDF.'):''}<div class="import-callout"><div><h3>Bring another company to the desk.</h3><p>Import a text-based annual report or transcript. Page-aware extraction makes it searchable without a model key.</p></div><button class="outline-button" data-action="import">Add a source ＋</button></div><p class="micro-note">Seed sources are official company disclosures. Uploaded documents stay in this browser’s document library; their provenance is not independently verified. Parsing sends the PDF to this app’s server; model-enabled research sends retrieved passages to the configured provider.</p>`}
 function renderSaved(){return `<div class="edition"><span class="eyebrow">IDEAS TO COME BACK TO</span><span class="edition-right">SAVED ON THIS DEVICE</span></div>${heading('Leave a trail<br><em>for your future self.</em>','Bookmarked signals and research notes, with their sources attached.')}${state.saved.length?state.saved.map(s=>`<article class="saved-card"><span class="saved-label">${s.kind==='research'?'▤':'⌑'}</span><div class="saved-body"><span class="saved-label">${escape(s.ticker)} · ${s.kind==='research'?'RESEARCH NOTE':'BOOKMARKED SIGNAL'}</span><h3>${escape(s.title)}</h3><p>${escape(s.description||'')}</p><button data-action="open-saved" data-id="escape-${escape(s.id)}">Return to the note ↗</button></div><button class="remove-note" data-action="remove-saved" data-id="${escape(s.id)}">Remove ×</button></article>`).join(''):empty('A clean page.','Bookmark a signal or save a research result. It will be here when you come back.',`<button class="outline-button" data-view="briefing">Back to the briefing ↗</button>`)}`}
 function openModal(title,body){$('#modal-content').innerHTML=`<div class="modal-header"><h2 id="modal-title">${escape(title)}</h2><button class="close-modal" data-action="close-modal" aria-label="Close dialog">×</button></div>${body}`;if(!modal.open)modal.showModal()}
 function showSettings(){openModal('Tune your signals.',`<div class="eyebrow">WHAT COUNTS AS UNUSUAL?</div><form id="preferences-form"><div class="setting-row"><div><strong>Daily price move</strong><p>Flag completed sessions with an absolute move above this percentage.</p></div><label><span class="sr-only">Price threshold percentage</span><input type="number" name="price" min="0.1" max="50" step="0.1" value="${state.prefs.priceThreshold}" required></label></div><div class="setting-row"><div><strong>Unusual volume</strong><p>Multiple of the previous 20 available completed sessions’ average, excluding the current session.</p></div><label><span class="sr-only">Volume threshold multiple</span><input type="number" name="volume" min="1" max="20" step="0.1" value="${state.prefs.volumeThreshold}" required></label></div><p class="check-note">Thresholds apply when you request a company’s Market view. This prototype does not monitor in the background.</p><div class="setting-row"><div><strong>Model connection</strong><p>${state.library.providerConfigured?'A server-side provider is configured. Research can run the bounded tool loop.':'No provider connected. Original-document retrieval works now; synthesis needs a server-side connection.'}</p></div><span class="pill ${state.library.providerConfigured?'':'uncovered'}">${state.library.providerConfigured?'Connected':'Evidence mode'}</span></div><p class="check-note">Provider-agnostic configuration lives on the server. Do not put a key into browser code.</p><pre class="settings-code">FINN_PROVIDER=${escape(state.library.provider||'gemini')}
FINN_MODEL=${escape(state.library.model||'gemini-3.1-flash-lite')}
GEMINI_API_KEY=server-side-secret</pre><button class="solid-button" type="submit">Save preferences</button><p class="check-note">Preferences and saved notes are local to this device.</p></form>`)}
 function showImport(ticker=state.ticker){openModal('Bring the source.',`<p class="notebook-subtitle">A text-based company PDF becomes searchable evidence. No model key required.</p><form id="import-form"><div class="field"><label for="upload-file">ORIGINAL PDF</label><input id="upload-file" name="file" type="file" accept="application/pdf,.pdf" required><small>Up to 15 MB and 350 pages. Scanned documents need OCR first.</small></div><div class="field-row"><div class="field"><label for="upload-ticker">NSE TICKER</label><input id="upload-ticker" name="ticker" value="${escape(ticker)}" maxlength="24" required placeholder="e.g. INFY"></div><div class="field"><label for="upload-type">DOCUMENT TYPE</label><select id="upload-type" name="type"><option value="transcript">Earnings-call transcript</option><option value="annual_report">Annual report</option></select></div></div><div class="field-row"><div class="field"><label for="upload-period">REPORTING PERIOD</label><input id="upload-period" name="period" placeholder="e.g. Q2 FY27" maxlength="50" required></div><div class="field"><label for="upload-date">DOCUMENT DATE</label><input id="upload-date" name="date" type="date" required></div></div><p class="check-note">The PDF is sent to this app’s server for parsing. Its extracted text is saved on this device. Source authenticity is your responsibility.</p><button class="solid-button" type="submit" id="import-submit">Extract & add to library ↗</button><div id="import-status" role="status"></div></form>`)}
 async function investigate(query,ticker=state.ticker){if(state.busy)return;state.workspaceTickers=[];state.ticker=String(ticker).trim().toUpperCase().replace(/\.(NS|BO)$/,'');state.query=query.trim();state.busy=true;state.result=null;state.stage='Searching the indexed disclosures for '+state.ticker+'.';const requestTicker=state.ticker;state.request=new AbortController();setView('research');try{state.result={...await post('/api/research',{query:state.query,ticker:requestTicker,extraCorpus:extraCorpus()},state.request.signal),scope:[requestTicker]}}catch(e){if(e.name==='AbortError'){toast('Research request cancelled.')}else state.result={mode:'evidence',query:state.query,summary:'The research request could not be completed.',findings:[],evidence:[],trace:[],gaps:[e.message]}}finally{state.busy=false;state.request=null;if(state.view==='research'){render();if(innerWidth<941)$('#research-output')?.scrollIntoView({behavior:'smooth',block:'start'})}}}
 function showEvidence(e){openModal('Read the evidence.',`<div class="modal-source"><div class="eyebrow">${escape(e.ticker)} · PAGE ${e.page}</div><h3>${escape(e.document?.title)}</h3><p class="case-caption">${escape(e.document?.period)} · ${escape(date(e.document?.date))}</p><blockquote>${escape(e.text)}</blockquote>${sourceLink(e.document,'Open the original PDF · page '+e.page+' ↗',e.page)}</div>`)}
 function bookmark(id){const b=state.briefs.find(b=>b.id===id);if(!b)return;const existing=state.saved.some(s=>s.id===id);const next=existing?state.saved.filter(s=>s.id!==id):[{id,kind:'signal',ticker:b.ticker,title:b.headline,description:b.deck},...state.saved];if(persist('finn-saved',next)){state.saved=next;render();toast(existing?'Bookmark removed.':'Signal saved on this device.')}}
 function saveResearch(){const r=currentResult();if(!r)return;const id='research-'+Date.now();const next=[{id,kind:'research',ticker:r.scope?.[0]||r.reviewContext?.ticker||state.ticker,title:r.query,description:r.summary,result:r},...state.saved].slice(0,30);if(persist('finn-saved',next)){state.saved=next;toast('Research note saved on this device.')}}
 function exportResearch(){const r=currentResult();if(!r)return;const text=`# ${r.query}\n\nCompany: ${(r.scope?.join(' × ')||r.reviewContext?.ticker||state.ticker)}\nMode: ${r.mode}\nGenerated: ${r.generatedAt||new Date().toISOString()}\n\n${r.summary}\n\n${r.findings.map(f=>'- '+f.text+' ['+f.evidenceIds.map(id=>r.evidence.findIndex(e=>e.id===id)+1).join(', ')+']').join('\n')}\n\n## Evidence\n\n${r.evidence.map((e,i)=>`### [${i+1}] ${e.document.title} — page ${e.page}\n\n${e.text}\n\n${e.document.url?sourceURL(e):'Uploaded on this device'}`).join('\n\n')}\n\n## Gaps\n\n${r.gaps.map(g=>'- '+g).join('\n')}\n`;const link=document.createElement('a');const blobURL=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));link.href=blobURL;link.download='FINN-'+(r.scope?.join('-')||r.reviewContext?.ticker||state.ticker)+'-research.md';link.click();setTimeout(()=>URL.revokeObjectURL(blobURL),1000)}
 async function discover(ticker){openModal('Find the original.',`<p class="notebook-subtitle">Searching for ${escape(ticker)} annual reports and earnings transcripts.</p><div id="discovery-result"><span class="loader"></span>Discovering source links…</div>`);try{const r=await api('/api/discover?ticker='+encodeURIComponent(ticker));const target=$('#discovery-result');if(!target)return;target.innerHTML=`<div class="eyebrow">${escape(ticker)} / DISCLOSURE LINKS</div><ul class="discovery-list">${r.links.map(l=>`<li><a href="${escape(safeURL(l.url))}" target="_blank" rel="noopener noreferrer">${escape(l.label)} ↗</a><span class="source-type">${l.type==='transcript'?'TRANSCRIPT':'ANNUAL REPORT'}</span></li>`).join('')}</ul>${!r.links.length?'<p class="check-note">No matching document links were found. Try the company’s investor-relations page.</p>':''}<p class="check-note">${escape(r.note)}</p><button class="solid-button" data-action="import" data-ticker="${escape(ticker)}">Import a downloaded PDF ＋</button>`}catch(e){const target=$('#discovery-result');if(target)target.innerHTML=`<div class="error-panel">${escape(e.message)}</div><button class="outline-button" data-action="import" data-ticker="${escape(ticker)}">Import a PDF instead ＋</button>`}}
 async function market(ticker){state.ticker=ticker;const panel=$('#quote-panel');if(!panel)return;panel.innerHTML='<div class="portfolio-quote"><span class="loader"></span>Loading completed market sessions…</div>';panel.scrollIntoView({behavior:'smooth',block:'start'});try{const q=await api('/api/quote?ticker='+encodeURIComponent(ticker));if(!$('#quote-panel')||state.ticker!==ticker)return;const values=q.history.map(d=>d.close),lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1;const points=values.map((v,i)=>`${i/(values.length-1)*600},${86-(v-lo)/span*70}`).join(' ');const alerts=[];if(Math.abs(q.changePercent)>state.prefs.priceThreshold)alerts.push('Price move exceeded your ±'+state.prefs.priceThreshold+'% threshold.');if(q.volumeRatio>state.prefs.volumeThreshold)alerts.push('Volume exceeded your '+state.prefs.volumeThreshold+'× threshold.');$('#quote-panel').innerHTML=`<section class="portfolio-quote"><div class="quote-top"><div><div class="eyebrow">${escape(company(ticker))} · ${escape(q.date)} EOD</div><div class="quote-price">₹${q.close.toLocaleString('en-IN',{maximumFractionDigits:2})}<span class="quote-change ${q.changePercent>=0?'positive':'negative'}">${q.changePercent>=0?'+':''}${q.changePercent.toFixed(2)}%</span></div></div><button class="outline-button" data-action="exchange" data-ticker="${escape(ticker)}">Exchange filings ↗</button></div><svg class="sparkline" viewBox="0 0 600 100" preserveAspectRatio="none" role="img" aria-label="Last ${q.history.length} completed daily closing prices"><polyline points="${points}" fill="none" stroke="#54764a" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div class="quote-stats"><div><small>VOLUME</small>${q.volume.toLocaleString('en-IN')}</div><div><small>VS PRIOR ${q.averageSessions} SESSIONS</small>${q.volumeRatio?.toFixed(2)||'—'}×</div><div><small>YOUR ALERTS</small>${alerts.length?escape(alerts.join(' ')):'No configured threshold crossed.'}</div></div><p class="micro-note">${escape(q.source)} · Fetched ${escape(new Date(q.fetchedAt).toLocaleTimeString('en-IN'))}. Corporate actions may affect unadjusted price comparisons.</p><div id="exchange-result"></div></section>`}catch(e){if($('#quote-panel'))$('#quote-panel').innerHTML=`<div class="error-panel">${escape(ticker)}: ${escape(e.message)}<br>Prices are not fabricated when the provider is unavailable. <button class="text-button" data-action="exchange" data-ticker="${escape(ticker)}">Try exchange filings ↗</button><div id="exchange-result"></div></div>`}}
 async function exchange(ticker){const target=$('#exchange-result');if(!target)return;target.innerHTML='<p><span class="loader"></span>Requesting exchange disclosures…</p>';try{const rows=await api('/api/announcements?ticker='+encodeURIComponent(ticker));if(!$('#exchange-result'))return;$('#exchange-result').innerHTML=`<section class="live-feed"><h3>Exchange disclosures.</h3>${rows.length?rows.map(r=>`<article><h4>${escape(r.subject)}</h4><p>${escape(r.details)}<br>${escape(r.date)}</p>${sourceLink({url:r.url},'Original exchange filing ↗')}</article>`).join(''):'<p>No announcements returned for this request.</p>'}</section>`}catch(e){if($('#exchange-result'))$('#exchange-result').innerHTML=`<p class="check-note">${escape(e.message)}</p>`}}
 function quoteCell(ticker){
  const q=state.quoteMap[ticker];if(!q)return `<span class="quote-pending">${state.pricesLoading?'Loading…':'—'}</span>`;
  if(!Number.isFinite(q.price))return `<span class="quote-error">Unavailable</span><small>${escape(q.error||'No quote returned')}</small>`;
  const age=new Date(q.asOf).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'});
  return `<button class="quote-value" data-action="quote-details" data-ticker="${escape(ticker)}" aria-label="${escape(ticker)} quote details: ${escape(money(q.price))}">${money(q.price)}</button><span class="quote-delta ${q.changePercent===null?'':q.changePercent>=0?'up':'down'}">${q.changePercent===null?'Change unavailable':(q.changePercent>=0?'+':'')+q.changePercent.toFixed(2)+'%'}</span><small class="quote-time ${q.stale?'stale':''}">${q.stale?'Cached · ':''}${escape(age)} IST</small>`;
 }
 function renderTracker(){return `<section class="price-tracker" aria-label="Portfolio price tracker"><div class="price-tracker-top"><div><span class="eyebrow"><i></i>THE MARKET TAPE</span><p id="price-status" role="status">Latest provider quotes for every company in your portfolio.</p></div><div class="price-controls"><button class="text-button" data-action="toggle-price-auto" id="price-auto" aria-pressed="${state.priceAuto}">Auto refresh ${state.priceAuto?'on':'off'}</button><button class="outline-button" data-action="refresh-prices" id="price-refresh">Refresh ↻</button></div></div><p class="price-caption">Updates every 60 seconds while this page is visible. Yahoo Finance quotes may be delayed; tap a price for its timestamp and session status.</p></section>`}
 function paintQuotes(){
  if(state.view!=='portfolio')return;document.querySelectorAll('[data-quote-ticker]').forEach(cell=>cell.innerHTML=quoteCell(cell.dataset.quoteTicker));
  const all=watchlist(),rows=all.map(c=>state.quoteMap[c.ticker]).filter(Boolean),available=rows.filter(q=>Number.isFinite(q.price)),stale=available.filter(q=>q.stale),open=available.filter(q=>q.marketState==='open').length;
  const status=$('#price-status');if(status)status.textContent=state.pricesLoading?'Updating '+all.length+' companies · '+available.length+' quotes available…':state.priceError?state.priceError:available.length+' / '+all.length+' quotes available · '+(open?'Market session open':available.length?'Market session closed or unavailable':'Waiting for provider')+(stale.length?' · '+stale.length+' cached':'')+(state.priceLastAt?' · refreshed '+new Date(state.priceLastAt).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Asia/Kolkata'})+' IST':'');
  const refresh=$('#price-refresh');if(refresh){refresh.disabled=state.pricesLoading;refresh.textContent=state.pricesLoading?'Updating…':'Refresh ↻'}
  const auto=$('#price-auto');if(auto){auto.textContent='Auto refresh '+(state.priceAuto?'on':'off');auto.setAttribute('aria-pressed',String(state.priceAuto))}
 }
 function pausePrices(){clearTimeout(priceTimer);priceTimer=null}
 async function refreshPrices(){
  pausePrices();if(state.pricesLoading||state.view!=='portfolio'||document.hidden)return;
  const tickers=watchlist().map(c=>c.ticker);if(!tickers.length)return;state.pricesLoading=true;state.priceError='';paintQuotes();
  try{for(let start=0;start<tickers.length;start+=20){if(state.view!=='portfolio'||document.hidden)break;const batch=tickers.slice(start,start+20);try{const result=await api('/api/quotes?tickers='+encodeURIComponent(batch.join(',')));result.quotes.forEach(q=>{const old=state.quoteMap[q.ticker];state.quoteMap[q.ticker]=!Number.isFinite(q.price)&&Number.isFinite(old?.price)?{...old,stale:true,marketState:'unknown',error:q.error}:q});state.priceLastAt=result.fetchedAt}catch(error){for(const ticker of batch){const old=state.quoteMap[ticker];state.quoteMap[ticker]=old?.price?{...old,stale:true,error:'Refresh failed; showing the last successful quote.'}:{ticker,price:null,error:'Price provider unavailable.'}}state.priceError='Some quotes could not refresh. Last successful prices remain marked as cached.'}paintQuotes()}}
  finally{state.pricesLoading=false;paintQuotes();if(state.view==='portfolio'&&!document.hidden){if(tickers.join(',')!==watchlist().map(c=>c.ticker).join(','))priceTimer=setTimeout(refreshPrices,0);else if(state.priceAuto)priceTimer=setTimeout(refreshPrices,60000)}}
 }
 function showQuote(ticker){const q=state.quoteMap[ticker];if(!q||!Number.isFinite(q.price))return;const values=q.intraday?.map(p=>p.price)||[],lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1,points=values.map((p,i)=>`${i/Math.max(1,values.length-1)*600},${86-(p-lo)/span*70}`).join(' ');openModal(company(ticker)+' · market quote',`<div class="quote-dialog"><div class="eyebrow">${escape(ticker)} · ${escape(q.exchange)} · ${escape(q.currency)}</div><div class="quote-price">${money(q.price)}<span class="quote-change ${q.changePercent>=0?'positive':'negative'}">${q.changePercent===null?'—':(q.changePercent>=0?'+':'')+q.changePercent.toFixed(2)+'%'}</span></div>${values.length>1?`<svg class="sparkline" viewBox="0 0 600 100" preserveAspectRatio="none" role="img" aria-label="Recent provider intraday prices"><polyline points="${points}" fill="none" stroke="#54764a" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`:''}<div class="quote-detail-grid"><div><small>EXCHANGE TIMESTAMP</small>${escape(new Date(q.asOf).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))} IST</div><div><small>SESSION</small>${escape(q.marketState)}</div><div><small>PREVIOUS CLOSE</small>${q.previousClose===null?'Unavailable':money(q.previousClose)}</div><div><small>VOLUME</small>${q.volume===null?'Unavailable':q.volume.toLocaleString('en-IN')}</div></div><p class="micro-note">Source: ${escape(q.source)}. ${q.delayMinutes===null?'The provider does not specify a delay here.':q.delayMinutes+' minute provider delay.'} Quotes may be delayed. ${q.stale?'Refresh failed; this is the last successful cached quote.':''}</p><button class="outline-button" data-action="quote-research" data-ticker="${escape(ticker)}">Research this company ↗</button></div>`)}
 document.addEventListener('visibilitychange',()=>{if(document.hidden)pausePrices();else if(state.view==='portfolio'&&state.priceAuto)refreshPrices()});
 function renderThesis(){
  const current=activeThesis(),draft=state.thesisDraft||current||{ticker:state.ticker,thesis:'',disconfirm:'',lens:'business',nextReview:nextMonth()},latest=current?.reviews?.at(-1),lenses=state.diligence?.lenses||[];
  return `<div class="edition"><span class="eyebrow">CONVICTION, OPEN TO QUESTION</span><span class="edition-right">YOUR BELIEFS / THE COMPANY’S EVIDENCE</span></div>${heading('Hold the thesis.<br><em>Question the evidence.</em>','Write down what must be true. Look for what could change your mind.',`<button class="outline-button" data-action="research-method">Why these questions? ↗</button>`)}
  <div class="method-ribbon"><span>◇</span><p>Business quality. Management. Cash. Downside. Governance.</p><button class="text-button" data-action="research-method">The approach ↗</button></div>
  <div class="thesis-layout"><aside class="thesis-index"><div class="section-line"><h2 class="section-title">YOUR COMPANY FILES</h2><button class="text-button" data-action="new-thesis">＋ New</button></div>${state.theses.map(t=>`<button class="thesis-index-item ${t.id===state.activeThesis?'active':''}" data-action="select-thesis" data-id="${escape(t.id)}"><span>${escape(t.ticker)} <small>${t.reviews.length} review${t.reviews.length===1?'':'s'}</small></span><strong>${escape(t.thesis)}</strong><em>${t.nextReview<today()?'Review overdue':t.nextReview===today()?'Review due today':'Next review '+escape(date(t.nextReview))}</em></button>`).join('')||'<p class="micro-note">Your first thesis starts with a question, not a score. Saved files stay on this device.</p>'}<div class="thesis-examples"><div class="eyebrow">ILLUSTRATIVE STARTING POINTS</div><button data-action="example-thesis" data-template="growth">INFY · Growth & execution ↗</button><button data-action="example-thesis" data-template="cash">INFY · Profit into cash ↗</button><button data-action="example-thesis" data-template="capital">LT · Capital & execution ↗</button></div></aside>
  <section class="thesis-editor"><div class="notebook-top"><span>${current?'COMPANY FILE / '+escape(current.ticker):'A NEW COMPANY FILE'}</span><span class="result-status">ANALYST HYPOTHESIS</span></div>${draft.example?'<p class="example-note">Illustrative hypothesis. Edit it to reflect your view before saving.</p>':''}
  <form id="thesis-form"><div class="field-row"><div class="field"><label for="thesis-ticker">NSE TICKER</label><input id="thesis-ticker" name="ticker" value="${escape(draft.ticker)}" maxlength="24" required></div><div class="field"><label for="thesis-lens">RESEARCH LENS</label><select id="thesis-lens" name="lens">${lenses.map(l=>`<option value="${l.id}" ${l.id===draft.lens?'selected':''}>${escape(l.title)}</option>`).join('')}</select></div></div>
  <div class="field"><label for="thesis-belief">WHAT MUST BE TRUE?</label><textarea id="thesis-belief" name="thesis" minlength="10" maxlength="1000" required placeholder="State a company-specific belief that evidence could test.">${escape(draft.thesis)}</textarea></div><div class="field"><label for="thesis-disconfirm">WHAT WOULD CHANGE MY MIND?</label><textarea id="thesis-disconfirm" name="disconfirm" minlength="10" maxlength="1000" required placeholder="Name the observation, missed milestone or financial deterioration that would challenge it.">${escape(draft.disconfirm)}</textarea></div>
  <div class="thesis-form-bottom"><div class="field"><label for="thesis-next-review">NEXT REVIEW</label><input id="thesis-next-review" name="nextReview" type="date" value="${escape(draft.nextReview)}" required></div><div class="thesis-buttons"><button class="outline-button" name="intent" value="save" type="submit" ${state.thesisBusy?'disabled':''}>Save thesis</button><button class="solid-button" name="intent" value="review" type="submit" ${state.thesisBusy?'disabled':''}>${state.thesisBusy?'Reading both sides…':'Test against the sources'} ↗</button></div></div></form>
  <p class="micro-note">A review date is a reminder inside this file; it does not schedule background work. Your thesis is sent to the app server only when you test it. Model-enabled reviews also send it to the configured provider.</p>
  ${state.thesisBusy?'<div class="loading-result"><span class="loader"></span><h3>Looking for what holds up.<br>And what doesn’t.</h3><p>Searching your thesis and its disconfirming condition separately.</p></div>':latest?`<section class="thesis-review"><div class="section-line"><h3 class="section-title">LATEST SOURCE REVIEW</h3><span class="subtle">${escape(new Date(latest.at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</span></div>${current.ticker!==latest.result.reviewContext?.ticker||current.thesis!==latest.thesis||current.disconfirm!==latest.disconfirm||current.lens!==latest.lens?'<p class="example-note">This review belongs to an earlier version of your thesis. Test the updated version to refresh the evidence.</p>':''}${renderResult(latest.result)}</section>`:empty('The belief comes first.','Save your thesis, then test it against the available reports and transcripts. Missing evidence will remain a gap.')}
  ${current?.reviews?.length>1?`<details class="trace"><summary>EARLIER REVIEWS · ${current.reviews.length-1} saved snapshots</summary>${current.reviews.slice(0,-1).reverse().map((r,i)=>`<div class="review-history"><span>${escape(new Date(r.at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</span><p>${escape(r.thesis)}</p><small>${r.result.evidence.length} passages · ${r.result.mode==='agent'?'Model-assisted review':'Evidence retrieved'}</small><button class="text-button" data-action="historical-review" data-index="${current.reviews.length-2-i}">Inspect this snapshot ↗</button></div>`).join('')}</details>`:''}</section></div>`;
 }
 function showMethod(){openModal('A disciplined set of questions.',`<p class="notebook-subtitle">ENAM’s public investment approach emphasizes durable businesses, management’s use of capital, governance and preserving capital. This thesis file is our interpretation of those principles.</p><div class="method-lenses">${(state.diligence?.lenses||[]).map(l=>`<div class="case-source-row"><div><strong>${escape(l.title)}</strong><small>${escape(l.question)}</small></div><a class="source-link" href="${escape(l.source)}" target="_blank" rel="noopener noreferrer">Public source ↗</a></div>`).join('')}</div><p class="check-note">This is an assignment prototype, not an official ENAM product or a reproduction of its internal tools. Source lenses guide questions; they do not certify a company or produce an investment recommendation.</p>`)}
 function startExample(template){const templates={growth:{ticker:'INFY',lens:'management',thesis:'Management can convert demand and large-deal wins into revenue growth consistent with its stated guidance.',disconfirm:'Repeated downward guidance revisions or weak deal conversion would challenge this belief.'},cash:{ticker:'INFY',lens:'cash',thesis:'Reported profits are supported by operating cash generation rather than a build-up of receivables.',disconfirm:'Sustained deterioration in cash conversion or a rise in receivable days would challenge this belief.'},capital:{ticker:'LT',lens:'management',thesis:'A growing order book can translate into execution and revenue without an excessive working-capital burden.',disconfirm:'Execution delays or cash tied up in working capital beyond management expectations would challenge this belief.'}};state.activeThesis=null;state.thesisDraft={...templates[template],nextReview:nextMonth(),example:true};setView('thesis')}
 async function saveOrReviewThesis(form,intent){
  const data=new FormData(form),ticker=String(data.get('ticker')).trim().toUpperCase().replace(/\.NS$/,'');
  const thesis=String(data.get('thesis')).trim(),disconfirm=String(data.get('disconfirm')).trim(),lens=String(data.get('lens')),nextReview=String(data.get('nextReview'));
  if(!/^[A-Z0-9&-]{1,24}$/.test(ticker)||thesis.length<10||disconfirm.length<10||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(nextReview)){toast('Enter a valid ticker, thesis, disconfirming condition and review date.');return}
  const old=activeThesis(),saved={id:old?.id||crypto.randomUUID(),ticker,thesis,disconfirm,lens,nextReview,createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),reviews:old?.reviews||[]};
  const next=old?state.theses.map(t=>t.id===old.id?saved:t):[saved,...state.theses];if(!persist('finn-theses',next))return;state.theses=next;state.activeThesis=saved.id;state.thesisDraft=null;
  if(intent!=='review'){render();toast('Thesis saved on this device.');return}
  if(state.thesisBusy)return;state.thesisBusy=true;state.ticker=ticker;render();
  try{const result=await post('/api/review',{ticker,thesis,disconfirm,lens,extraCorpus:extraCorpus()});const snapshot={id:crypto.randomUUID(),at:new Date().toISOString(),thesis,disconfirm,lens,result};const updated=state.theses.map(t=>t.id===saved.id?{...t,reviews:[...t.reviews,snapshot].slice(-8)}:t);if(persist('finn-theses',updated)){state.theses=updated;toast('Source review saved with the thesis version.')}}catch(error){toast(error.message)}finally{state.thesisBusy=false;if(state.view==='thesis')render()}
 }
 function showHoldingsImport(){openModal('Bring your portfolio together.',`<p class="notebook-subtitle">One INR snapshot across your accounts. We combine each ticker and calculate its share of the total.</p><form id="holdings-form"><div class="field"><label for="holdings-file">HOLDINGS CSV</label><input id="holdings-file" name="file" type="file" accept=".csv,text/csv" required><small>Required: ticker, market_value. Optional: name, sector, account, currency. One row per account and ticker. Values in INR; up to 1,000 rows.</small></div><div class="field"><label for="holdings-date">SNAPSHOT AS OF</label><input id="holdings-date" name="asOf" type="date" value="${today()}" required></div><pre class="settings-code">ticker,name,sector,account,market_value
INFY,Infosys,Technology,Account A,120000
INFY,Infosys,Technology,Account B,80000
LT,Larsen &amp; Toubro,Industrials,Account A,100000</pre><p class="check-note">The sample values are illustrative. This generic CSV import is not an MProfit connection or a broker statement parser. Holdings values stay in this browser and are not sent to the server or model.</p><button class="solid-button" type="submit">Validate & import snapshot ↗</button><div id="holdings-status" role="status"></div></form>`)}
 function portfolioOverview(){if(!state.imported)return '';const data=portfolioTools.consolidate(state.imported.rows,state.accountFilter);return `<section class="allocation-panel"><div class="allocation-top"><div><div class="eyebrow">IMPORTED INR SNAPSHOT · ${escape(date(state.imported.asOf))}</div><div class="allocation-value">${money(data.total)}</div><p>${data.holdings.length} unique compan${data.holdings.length===1?'y':'ies'} · ${state.accountFilter==='all'?data.accounts.length:1} account${state.accountFilter==='all'&&data.accounts.length!==1?'s':''}</p></div><label><span class="sr-only">Portfolio account</span><select id="account-filter" class="window-select"><option value="all">All accounts</option>${data.accounts.map(a=>`<option value="${escape(a)}" ${state.accountFilter===a?'selected':''}>${escape(a)}</option>`).join('')}</select></label></div><div class="allocation-sectors"><h2 class="section-title">SECTOR EXPOSURE</h2>${data.sectors.map(s=>`<div class="allocation-row"><span>${escape(s.sector)}</span><div><i style="width:${s.weight||0}%"></i></div><strong>${s.weight===null?'—':s.weight.toFixed(1)+'%'}</strong></div>`).join('')}</div><p class="micro-note">Weights use your imported market values, not live repricing. Classification comes from your CSV. ${data.total===0?'A zero-value snapshot has no calculable weights.':''}</p><button class="text-button" data-action="clear-holdings">Return to the illustrative watchlist ↗</button></section>`}

 document.addEventListener('click',async event=>{
  const command=event.target.closest('[data-command]');if(command){runCommand(command.dataset.command);return}
  const nav=event.target.closest('[data-view]');if(nav){event.preventDefault();setView(nav.dataset.view);return}
  const filter=event.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return}
  const prompt=event.target.closest('[data-prompt]');if(prompt){const ticker=$('#research-ticker')?.value||state.ticker;investigate(researchPrompts()[Number(prompt.dataset.prompt)],ticker);return}
  const citation=event.target.closest('[data-evidence-id]');if(citation){const e=currentResult()?.evidence.find(e=>e.id===citation.dataset.evidenceId);if(e)showEvidence(e);return}
  const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
  if(action==='focus-command')$('#workspace-command').focus();
  else if(action==='command-help')showCommandHelp();
  else if(action==='apply-ticker'){state.ticker=String($('#research-ticker').value).trim().toUpperCase();state.result=null;state.workspaceTickers=[];state.query='';render()}
  else if(action==='refresh-overview')fetchWorkspaceQuotes(watchlist().slice(0,5).map(c=>c.ticker));
  else if(action==='case-passage'){const e=state.caseStudy?.evidence[Number(b.dataset.index)];if(e)showEvidence(e)}
  else if(action==='close-modal')modal.close();
  else if(action==='refresh-prices')refreshPrices();
  else if(action==='toggle-price-auto'){state.priceAuto=!state.priceAuto;if(state.priceAuto)refreshPrices();else pausePrices();paintQuotes()}
  else if(action==='quote-details')showQuote(b.dataset.ticker);
  else if(action==='quote-research'){modal.close();state.ticker=b.dataset.ticker;state.result=null;state.workspaceTickers=[];state.query='';setView('research')}
  else if(action==='research-method')showMethod();
  else if(action==='new-thesis'){state.activeThesis=null;state.thesisDraft=null;setView('thesis')}
  else if(action==='example-thesis')startExample(b.dataset.template);
  else if(action==='select-thesis'){state.activeThesis=b.dataset.id;state.thesisDraft=null;state.ticker=activeThesis()?.ticker||state.ticker;render()}
  else if(action==='company-thesis'){state.ticker=b.dataset.ticker;state.activeThesis=state.theses.find(t=>t.ticker===state.ticker)?.id||null;state.thesisDraft=null;setView('thesis')}
  else if(action==='historical-review'){const review=activeThesis()?.reviews[Number(b.dataset.index)];if(review){state.result=review.result;state.ticker=activeThesis().ticker;state.query=review.result.query;setView('research')}}
  else if(action==='import-holdings')showHoldingsImport();
  else if(action==='clear-holdings'){if(persist('finn-holdings',null)){state.imported=null;state.accountFilter='all';render();refreshPrices();toast('Illustrative watchlist restored.')}}
  else if(action==='preferences')showSettings();
  else if(action==='show-archive'){state.window='all';render()}
  else if(action==='bookmark')bookmark(b.dataset.id);
  else if(action==='open-case'){state.result=null;state.ticker='INFY';state.query='';setView('research')}
  else if(action==='research-brief'){const brief=state.briefs.find(i=>i.id===b.dataset.id);if(brief)investigate(brief.query,brief.ticker)}
  else if(action==='research-company'){state.ticker=b.dataset.ticker;state.result=null;state.workspaceTickers=[];state.query='';setView('research')}
  else if(action==='import')showImport(b.dataset.ticker||$('#research-ticker')?.value||state.ticker);
  else if(action==='new-company'){openModal('A wider circle.',`<form id="new-company-form"><div class="field"><label for="new-ticker">ANY NSE TICKER</label><input id="new-ticker" name="ticker" required maxlength="24" placeholder="e.g. PIDILITIND"></div><button class="solid-button" type="submit">Discover company sources ↗</button></form>`)}
  else if(action==='discover')discover(String(b.dataset.ticker||$('#research-ticker')?.value||state.ticker).trim().toUpperCase());
  else if(action==='case-research')investigate('How did Infosys FY26 revenue growth guidance change, and did final full-year growth meet the final range?','INFY');
  else if(action==='case-evidence'){openModal('The five source passages.',`<div class="modal-source"><p class="check-note">Four dated guidance statements and the full-year outcome. The file links use physical PDF page numbers.</p>${state.caseStudy.evidence.map(e=>`<div class="case-source-row"><div><strong>${escape(e.document.period)}</strong><small>${escape(date(e.document.date))} · PAGE ${e.page}</small></div>${sourceLink(e.document,'Read original ↗',e.page)}</div><blockquote style="font-size:11px">${escape(e.text)}</blockquote>`).join('')}</div>`)}
  else if(action==='save-research')saveResearch();
  else if(action==='export-research')exportResearch();
  else if(action==='cancel-research')state.request?.abort();
  else if(action==='market')market(b.dataset.ticker);
  else if(action==='exchange')exchange(b.dataset.ticker);
  else if(action==='remove-saved'){const next=state.saved.filter(s=>s.id!==b.dataset.id);if(persist('finn-saved',next)){state.saved=next;render()}}
  else if(action==='open-saved'){const s=state.saved.find(s=>'escape-'+s.id===b.dataset.id);if(s?.kind==='research'){state.result=s.result;state.query=s.title;state.ticker=s.ticker;setView('research')}else if(s){state.filter='saved';setView('briefing')}}
  else if(action==='delete-document'){try{await localDocs('delete',b.dataset.id);state.uploads=state.uploads.filter(u=>u.document.id!==b.dataset.id);render();toast('Uploaded document removed from this device.')}catch{toast('Could not remove the document.')}}
 });
 document.addEventListener('submit',async event=>{
  const form=event.target;event.preventDefault();
  if(form.id==='command-form'){runCommand(String(new FormData(form).get('prompt')))}
  else if(form.id==='research-form'){const data=new FormData(form);investigate(String(data.get('query')),String(data.get('ticker')))}
  else if(form.id==='thesis-form')saveOrReviewThesis(form,event.submitter?.value||'save');
  else if(form.id==='holdings-form'){
   const status=$('#holdings-status');try{const f=new FormData(form),file=f.get('file');if(!file||file.size>250000)throw new Error('Choose a CSV smaller than 250 KB.');const rows=portfolioTools.parseCSV(await file.text());portfolioTools.consolidate(rows);const value={rows,asOf:String(f.get('asOf')),importedAt:new Date().toISOString()};if(persist('finn-holdings',value)){state.imported=value;state.accountFilter='all';modal.close();setView('portfolio');toast(rows.length+' account positions consolidated on this device.')}}catch(error){status.innerHTML=`<div class="error-panel">${escape(error.message)}</div>`}
  }
  else if(form.id==='preferences-form'){const f=new FormData(form);const prefs={...state.prefs,priceThreshold:Number(f.get('price')),volumeThreshold:Number(f.get('volume'))};if(persist('finn-prefs',prefs)){state.prefs=prefs;modal.close();toast('Signal preferences saved.')}}
  else if(form.id==='new-company-form'){const ticker=String(new FormData(form).get('ticker')).trim().toUpperCase();if(!/^[A-Z0-9&-]{1,24}$/.test(ticker)){toast('Enter a valid NSE ticker.');return}state.ticker=ticker;discover(ticker)}
  else if(form.id==='import-form'){
   const button=$('#import-submit'),status=$('#import-status');button.disabled=true;status.innerHTML='<p class="check-note"><span class="loader"></span>Extracting page-aware passages…</p>';
   try{const body=new FormData(form);body.set('ticker',String(body.get('ticker')).trim().toUpperCase());const r=await api('/api/ingest',{method:'POST',body});await localDocs('put',r);state.uploads.push(r);state.ticker=r.document.ticker;modal.close();setView('library');toast(r.chunks.length+' searchable passages added on this device.')}catch(e){status.innerHTML=`<div class="error-panel">${escape(e.message)}</div>`;button.disabled=false}
  }
 });
 document.addEventListener('change',event=>{if(event.target.id==='account-filter'){state.accountFilter=event.target.value;render()}if(event.target.id==='brief-window'){state.window=event.target.value;render()}if(event.target.id==='research-ticker'){const t=event.target.value.trim().toUpperCase();state.ticker=t;const label=$('#company-label');if(label)label.textContent=company(t)+' · '+(covered(t)?'Documents indexed':'Add sources to research')}});
 document.addEventListener('input',event=>{if(event.target.id==='portfolio-search'||event.target.id==='library-search'){const pos=event.target.selectionStart,id=event.target.id;state.search=event.target.value;render();const input=$('#'+id);input.focus();input.setSelectionRange(pos,pos)}if(event.target.id==='research-question')state.query=event.target.value});
 $('#open-settings').addEventListener('click',showSettings);$('#top-settings').addEventListener('click',showSettings);
 modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close()}});
 window.addEventListener('hashchange',()=>setView(location.hash.slice(1),false));
 (async()=>{try{const [library,briefing,caseStudy,diligence]=await Promise.all([api('/api/library'),api('/api/briefing'),api('/api/case-study'),api('/api/diligence')]);state.library=library;state.briefs=briefing.items;state.caseStudy=caseStudy;state.diligence=diligence;try{state.uploads=await localDocs('getAll')}catch{toast('Document storage is unavailable in this browser. Seed sources remain searchable.')}$('#mode-label').textContent=library.providerConfigured?'GEMINI CONNECTED':'EVIDENCE MODE';$('#desk-clock').textContent=new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',timeZone:'Asia/Kolkata'}).format(new Date()).toUpperCase()+' / IST';setView(location.hash.slice(1)||'briefing');fetchWorkspaceQuotes(watchlist().slice(0,5).map(c=>c.ticker))}catch(e){main.innerHTML=empty('The desk couldn’t open.',e.message,`<button class="outline-button" onclick="location.reload()">Try again ↗</button>`)}})();
}
